{
  "name": "InstaSort",
  "description": "Organize your favorite Instagram accounts into beautiful, custom-colored categories with notes and sorting."
}

export interface Category {
  id: string;
  name: string;
  color: string;
  parentId?: string; // If undefined, it's a main category. If defined, it's a subcategory.
}

export interface Profile {
  id: string;
  username: string;
  categoryId: string;
  notes: string;
  createdAt: number;
}

export type SortOption = 'alphabetical' | 'newest' | 'oldest';

export const PASTEL_COLORS = [
  '#FFB3BA', // Red/Pink
  '#FFDFBA', // Orange
  '#FFFFBA', // Yellow
  '#BAFFC9', // Green
  '#BAE1FF', // Blue
  '#E2BAFF', // Purple
  '#F0F0F0', // Gray
  '#C9C9FF', // Indigo
];

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useEffect } from 'react';
import { Icons } from './Icon';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    if (isOpen) window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm transition-opacity">
      <div 
        className="bg-white dark:bg-slate-800 w-full max-w-md rounded-2xl shadow-2xl transform transition-all scale-100 overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between p-4 border-b dark:border-slate-700">
          <h3 className="text-lg font-semibold">{title}</h3>
          <button 
            onClick={onClose}
            className="p-1 rounded-full hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors"
          >
            <Icons.Plus className="w-6 h-6 rotate-45" />
          </button>
        </div>
        <div className="p-4 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Profile, Category } from '../types';
import { Icons } from './Icon';

interface ProfileCardProps {
  profile: Profile;
  category?: Category;
  onClick: (profile: Profile) => void;
  onEdit: (e: React.MouseEvent, profile: Profile) => void;
}

export const ProfileCard: React.FC<ProfileCardProps> = ({ profile, category, onClick, onEdit }) => {
  return (
    <div 
      onClick={() => onClick(profile)}
      className="group relative bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 hover:shadow-md hover:-translate-y-1 transition-all cursor-pointer flex items-center gap-4"
    >
      {/* Decorative colored strip based on category */}
      <div 
        className="absolute left-0 top-0 bottom-0 w-1.5 rounded-l-xl" 
        style={{ backgroundColor: category?.color || '#cbd5e1' }}
      />

      {/* Avatar Placeholder */}
      <div className="w-12 h-12 rounded-full bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 p-[2px] flex-shrink-0">
         <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
            <Icons.Instagram className="w-6 h-6 text-gray-400 dark:text-slate-400" />
         </div>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-semibold text-gray-900 dark:text-white truncate">
          @{profile.username}
        </h3>
        {profile.notes && (
           <p className="text-xs text-gray-500 dark:text-slate-400 truncate mt-0.5">
             {profile.notes}
           </p>
        )}
        {!profile.notes && (
            <p className="text-xs text-gray-400 dark:text-slate-500 italic mt-0.5">
              No notes
            </p>
        )}
      </div>

      <button 
        onClick={(e) => onEdit(e, profile)}
        className="p-2 opacity-0 group-hover:opacity-100 transition-opacity rounded-full hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-500"
      >
        <Icons.MoreVertical className="w-4 h-4" />
      </button>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'bonappetit', categoryId: '3', notes: 'Recipe ideas', createdAt: Date.now() - 20000 },
];

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('instasort_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('instasort_profiles');
    return saved ? JSON.parse(saved) : INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('instasort_theme') === 'dark';
    }
    return false;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortOption, setSortOption] = useState<SortOption>('newest');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('instasort_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('instasort_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('instasort_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('instasort_theme', 'light');
    }
  }, [darkMode]);

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       return matchesSearch && matchesCategory;
    });

    return result.sort((a, b) => {
      if (sortOption === 'alphabetical') return a.username.localeCompare(b.username);
      if (sortOption === 'newest') return b.createdAt - a.createdAt;
      if (sortOption === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, sortOption]);

  const rootCategories = categories.filter(c => !c.parentId);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    // Clean username (remove @ and url)
    let cleanUser = newProfileUsername.trim();
    if (cleanUser.includes('instagram.com/')) {
       const parts = cleanUser.split('instagram.com/');
       cleanUser = parts[1].split('/')[0].split('?')[0];
    }
    cleanUser = cleanUser.replace('@', '');

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6">
          <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500 flex items-center gap-2">
            <Icons.Instagram className="text-pink-500 w-8 h-8" />
            InstaSort
          </h1>
        </div>

        <div className="px-4 py-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {rootCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <button
                onClick={() => setSelectedCategoryId(cat.id)}
                className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                  selectedCategoryId === cat.id 
                    ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                    : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
                }`}
              >
                <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                <span className="truncate flex-1">{cat.name}</span>
              </button>

              {/* Subcategories */}
              {categories.filter(sub => sub.parentId === cat.id).map(sub => (
                <button
                  key={sub.id}
                  onClick={() => setSelectedCategoryId(sub.id)}
                  className={`w-full flex items-center gap-3 pl-10 pr-4 py-2 rounded-xl text-left text-sm transition-all ${
                    selectedCategoryId === sub.id 
                      ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                      : 'text-gray-500 dark:text-slate-500 hover:text-gray-900'
                  }`}
                >
                  <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                  <span className="truncate">{sub.name}</span>
                </button>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800">
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <h1 className="text-xl font-bold flex items-center gap-2">
             <Icons.Instagram className="text-pink-500 w-6 h-6" />
             InstaSort
          </h1>
          <button onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? <Icons.Sun className="w-6 h-6" /> : <Icons.Moon className="w-6 h-6" />}
          </button>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire Instagram collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search usernames or notes..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>
              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category Select */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <select 
                    className="bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-2 focus:ring-pink-500"
                    value={sortOption}
                    onChange={(e) => setSortOption(e.target.value as SortOption)}
                 >
                   <option value="newest">Newest First</option>
                   <option value="oldest">Oldest First</option>
                   <option value="alphabetical">A-Z</option>
                 </select>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Instagram Profile">
         <div className="space-y-4">
           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Instagram Username or URL</label>
             <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">@</span>
                <input 
                  type="text" 
                  className="w-full pl-8 p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all"
                  placeholder="username or paste profile URL"
                  value={newProfileUsername}
                  onChange={(e) => setNewProfileUsername(e.target.value)}
                  autoFocus
                />
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2">
                {categories.map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {rootCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="w-24 h-24 rounded-full p-[3px] bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 mb-4 shadow-lg">
                <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
                   <Icons.Instagram className="w-10 h-10 text-gray-300" />
                </div>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">@{selectedProfile.username}</h2>
              <div 
                className="mt-2 px-3 py-1 rounded-full text-sm font-medium"
                style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
              >
                {getCategoryName(selectedProfile.categoryId)}
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={`https://instagram.com/${selectedProfile.username}`}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open in Instagram
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

export interface Category {
  id: string;
  name: string;
  color: string;
  parentId?: string; // If undefined, it's a main category. If defined, it's a subcategory.
}

export interface Profile {
  id: string;
  username: string;
  categoryId: string;
  notes: string;
  createdAt: number;
}

export type SortOption = 'a-z' | 'z-a' | 'newest' | 'oldest';

export const PASTEL_COLORS = [
  '#FFB3BA', // Red/Pink
  '#FFDFBA', // Orange
  '#FFFFBA', // Yellow
  '#BAFFC9', // Green
  '#BAE1FF', // Blue
  '#E2BAFF', // Purple
  '#F0F0F0', // Gray
  '#C9C9FF', // Indigo
];

import React, { useState, useEffect, useMemo } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'bonappetit', categoryId: '3', notes: 'Recipe ideas', createdAt: Date.now() - 20000 },
];

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('instasort_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('instasort_profiles');
    return saved ? JSON.parse(saved) : INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('instasort_theme') === 'dark';
    }
    return false;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Sorting State
  const [profileSort, setProfileSort] = useState<SortOption>('newest');
  const [categorySort, setCategorySort] = useState<SortOption>('a-z');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('instasort_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('instasort_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('instasort_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('instasort_theme', 'light');
    }
  }, [darkMode]);

  // --- Helpers ---
  const sortCategories = (cats: Category[]) => {
    return [...cats].sort((a, b) => {
      if (categorySort === 'a-z') return a.name.localeCompare(b.name);
      if (categorySort === 'z-a') return b.name.localeCompare(a.name);
      // Using ID as proxy for creation time since IDs are Date.now() or sequential
      if (categorySort === 'newest') return b.id.localeCompare(a.id);
      if (categorySort === 'oldest') return a.id.localeCompare(b.id);
      return 0;
    });
  };

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       return matchesSearch && matchesCategory;
    });

    return result.sort((a, b) => {
      if (profileSort === 'a-z') return a.username.localeCompare(b.username);
      if (profileSort === 'z-a') return b.username.localeCompare(a.username);
      if (profileSort === 'newest') return b.createdAt - a.createdAt;
      if (profileSort === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, profileSort]);

  // Process categories for display (sorted root, sorted sub)
  const displayCategories = useMemo(() => {
    const root = categories.filter(c => !c.parentId);
    const sortedRoot = sortCategories(root);

    return sortedRoot.map(cat => ({
      ...cat,
      children: sortCategories(categories.filter(sub => sub.parentId === cat.id))
    }));
  }, [categories, categorySort]);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    // Clean username (remove @ and url)
    let cleanUser = newProfileUsername.trim();
    if (cleanUser.includes('instagram.com/')) {
       const parts = cleanUser.split('instagram.com/');
       cleanUser = parts[1].split('/')[0].split('?')[0];
    }
    cleanUser = cleanUser.replace('@', '');

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6">
          <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500 flex items-center gap-2">
            <Icons.Instagram className="text-pink-500 w-8 h-8" />
            InstaSort
          </h1>
        </div>

        <div className="px-4 py-2 space-y-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>

          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-800 rounded-lg p-1.5">
             <Icons.ArrowUpDown className="w-4 h-4 text-gray-400 ml-2" />
             <select 
               value={categorySort}
               onChange={(e) => setCategorySort(e.target.value as SortOption)}
               className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 w-full focus:outline-none cursor-pointer border-none p-0 pr-2"
             >
               <option value="a-z">Name (A-Z)</option>
               <option value="z-a">Name (Z-A)</option>
               <option value="newest">Newest</option>
               <option value="oldest">Oldest</option>
             </select>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {displayCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <button
                onClick={() => setSelectedCategoryId(cat.id)}
                className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                  selectedCategoryId === cat.id 
                    ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                    : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
                }`}
              >
                <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                <span className="truncate flex-1">{cat.name}</span>
              </button>

              {/* Subcategories */}
              {cat.children.map(sub => (
                <button
                  key={sub.id}
                  onClick={() => setSelectedCategoryId(sub.id)}
                  className={`w-full flex items-center gap-3 pl-10 pr-4 py-2 rounded-xl text-left text-sm transition-all ${
                    selectedCategoryId === sub.id 
                      ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                      : 'text-gray-500 dark:text-slate-500 hover:text-gray-900'
                  }`}
                >
                  <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                  <span className="truncate">{sub.name}</span>
                </button>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800">
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <h1 className="text-xl font-bold flex items-center gap-2">
             <Icons.Instagram className="text-pink-500 w-6 h-6" />
             InstaSort
          </h1>
          <button onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? <Icons.Sun className="w-6 h-6" /> : <Icons.Moon className="w-6 h-6" />}
          </button>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire Instagram collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search usernames or notes..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>
              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category Select */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <div className="flex items-center gap-2 px-2">
                   <Icons.ArrowUpDown className="w-4 h-4 text-gray-400" />
                   <select 
                      className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-0"
                      value={profileSort}
                      onChange={(e) => setProfileSort(e.target.value as SortOption)}
                   >
                     <option value="newest">Newest First</option>
                     <option value="oldest">Oldest First</option>
                     <option value="a-z">Username (A-Z)</option>
                     <option value="z-a">Username (Z-A)</option>
                   </select>
                 </div>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Instagram Profile">
         <div className="space-y-4">
           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Instagram Username or URL</label>
             <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">@</span>
                <input 
                  type="text" 
                  className="w-full pl-8 p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all"
                  placeholder="username or paste profile URL"
                  value={newProfileUsername}
                  onChange={(e) => setNewProfileUsername(e.target.value)}
                  autoFocus
                />
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {displayCategories.flatMap(cat => [
                   cat,
                   ...cat.children
                ]).map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {displayCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="w-24 h-24 rounded-full p-[3px] bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 mb-4 shadow-lg">
                <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
                   <Icons.Instagram className="w-10 h-10 text-gray-300" />
                </div>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">@{selectedProfile.username}</h2>
              <div 
                className="mt-2 px-3 py-1 rounded-full text-sm font-medium"
                style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
              >
                {getCategoryName(selectedProfile.categoryId)}
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={`https://instagram.com/${selectedProfile.username}`}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open in Instagram
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'bonappetit', categoryId: '3', notes: 'Recipe ideas', createdAt: Date.now() - 20000 },
];

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('instasort_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('instasort_profiles');
    return saved ? JSON.parse(saved) : INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('instasort_theme') === 'dark';
    }
    return false;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Sorting State
  const [profileSort, setProfileSort] = useState<SortOption>('newest');
  const [categorySort, setCategorySort] = useState<SortOption>('a-z');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('instasort_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('instasort_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('instasort_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('instasort_theme', 'light');
    }
  }, [darkMode]);

  // --- Helpers ---
  const sortCategories = (cats: Category[]) => {
    return [...cats].sort((a, b) => {
      if (categorySort === 'a-z') return a.name.localeCompare(b.name);
      if (categorySort === 'z-a') return b.name.localeCompare(a.name);
      // Using ID as proxy for creation time since IDs are Date.now() or sequential
      if (categorySort === 'newest') return b.id.localeCompare(a.id);
      if (categorySort === 'oldest') return a.id.localeCompare(b.id);
      return 0;
    });
  };

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       return matchesSearch && matchesCategory;
    });

    return result.sort((a, b) => {
      if (profileSort === 'a-z') return a.username.localeCompare(b.username);
      if (profileSort === 'z-a') return b.username.localeCompare(a.username);
      if (profileSort === 'newest') return b.createdAt - a.createdAt;
      if (profileSort === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, profileSort]);

  // Process categories for display (sorted root, sorted sub)
  const displayCategories = useMemo(() => {
    const root = categories.filter(c => !c.parentId);
    const sortedRoot = sortCategories(root);

    return sortedRoot.map(cat => ({
      ...cat,
      children: sortCategories(categories.filter(sub => sub.parentId === cat.id))
    }));
  }, [categories, categorySort]);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    // Clean username (remove @ and url)
    let cleanUser = newProfileUsername.trim();
    if (cleanUser.includes('instagram.com/')) {
       const parts = cleanUser.split('instagram.com/');
       cleanUser = parts[1].split('/')[0].split('?')[0];
    }
    cleanUser = cleanUser.replace('@', '');

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleDeleteCategory = (id: string) => {
    if (!window.confirm("Are you sure? This will delete the category and uncategorize its profiles. Subcategories will also be deleted.")) {
      return;
    }

    // Identify IDs to remove (parent + children)
    const childrenIds = categories.filter(c => c.parentId === id).map(c => c.id);
    const idsToDelete = [id, ...childrenIds];

    // Remove categories
    setCategories(prev => prev.filter(c => !idsToDelete.includes(c.id)));

    // Reset selection if the currently selected category is deleted
    if (selectedCategoryId && idsToDelete.includes(selectedCategoryId)) {
      setSelectedCategoryId(null);
    }

    // Uncategorize profiles that were in these categories
    setProfiles(prev => prev.map(p => 
       idsToDelete.includes(p.categoryId) ? { ...p, categoryId: '' } : p
    ));
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6">
          <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500 flex items-center gap-2">
            <Icons.Instagram className="text-pink-500 w-8 h-8" />
            InstaSort
          </h1>
        </div>

        <div className="px-4 py-2 space-y-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>

          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-800 rounded-lg p-1.5">
             <Icons.ArrowUpDown className="w-4 h-4 text-gray-400 ml-2" />
             <select 
               value={categorySort}
               onChange={(e) => setCategorySort(e.target.value as SortOption)}
               className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 w-full focus:outline-none cursor-pointer border-none p-0 pr-2"
             >
               <option value="a-z">Name (A-Z)</option>
               <option value="z-a">Name (Z-A)</option>
               <option value="newest">Newest</option>
               <option value="oldest">Oldest</option>
             </select>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {displayCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <div className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors">
                 <button
                  onClick={() => setSelectedCategoryId(cat.id)}
                  className={`flex-1 flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                    selectedCategoryId === cat.id 
                      ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                      : 'text-gray-600 dark:text-slate-400'
                  }`}
                >
                  <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                  <span className="truncate flex-1">{cat.name}</span>
                </button>
                <button 
                   onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat.id); }}
                   className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                   title="Delete Category"
                >
                   <Icons.Trash2 className="w-4 h-4" />
                </button>
               </div>

              {/* Subcategories */}
              {cat.children.map(sub => (
                <div key={sub.id} className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors ml-6">
                    <button
                      onClick={() => setSelectedCategoryId(sub.id)}
                      className={`flex-1 flex items-center gap-3 px-4 py-2 rounded-xl text-left text-sm transition-all ${
                        selectedCategoryId === sub.id 
                          ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                          : 'text-gray-500 dark:text-slate-500'
                      }`}
                    >
                      <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                      <span className="truncate">{sub.name}</span>
                    </button>
                    <button 
                       onClick={(e) => { e.stopPropagation(); handleDeleteCategory(sub.id); }}
                       className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                       title="Delete Subcategory"
                    >
                       <Icons.Trash2 className="w-3.5 h-3.5" />
                    </button>
                </div>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800">
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <h1 className="text-xl font-bold flex items-center gap-2">
             <Icons.Instagram className="text-pink-500 w-6 h-6" />
             InstaSort
          </h1>
          <button onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? <Icons.Sun className="w-6 h-6" /> : <Icons.Moon className="w-6 h-6" />}
          </button>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire Instagram collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search usernames or notes..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>
              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category Select */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <div className="flex items-center gap-2 px-2">
                   <Icons.ArrowUpDown className="w-4 h-4 text-gray-400" />
                   <select 
                      className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-0"
                      value={profileSort}
                      onChange={(e) => setProfileSort(e.target.value as SortOption)}
                   >
                     <option value="newest">Newest First</option>
                     <option value="oldest">Oldest First</option>
                     <option value="a-z">Username (A-Z)</option>
                     <option value="z-a">Username (Z-A)</option>
                   </select>
                 </div>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Instagram Profile">
         <div className="space-y-4">
           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Instagram Username or URL</label>
             <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">@</span>
                <input 
                  type="text" 
                  className="w-full pl-8 p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all"
                  placeholder="username or paste profile URL"
                  value={newProfileUsername}
                  onChange={(e) => setNewProfileUsername(e.target.value)}
                  autoFocus
                />
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {displayCategories.flatMap(cat => [
                   cat,
                   ...cat.children
                ]).map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {displayCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="w-24 h-24 rounded-full p-[3px] bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 mb-4 shadow-lg">
                <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
                   <Icons.Instagram className="w-10 h-10 text-gray-300" />
                </div>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">@{selectedProfile.username}</h2>
              <div 
                className="mt-2 px-3 py-1 rounded-full text-sm font-medium"
                style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
              >
                {getCategoryName(selectedProfile.categoryId)}
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={`https://instagram.com/${selectedProfile.username}`}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open in Instagram
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

{
  "name": "Keepy",
  "description": "Organize your favorite Instagram accounts into beautiful, custom-colored categories with notes and sorting."
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'bonappetit', categoryId: '3', notes: 'Recipe ideas', createdAt: Date.now() - 20000 },
];

interface Branding {
  icon?: string;
  logoLight?: string;
  logoDark?: string;
}

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('keepy_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('keepy_profiles');
    return saved ? JSON.parse(saved) : INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('keepy_theme') === 'dark';
    }
    return false;
  });

  const [branding, setBranding] = useState<Branding>(() => {
    const saved = localStorage.getItem('keepy_branding');
    return saved ? JSON.parse(saved) : {};
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Sorting State
  const [profileSort, setProfileSort] = useState<SortOption>('newest');
  const [categorySort, setCategorySort] = useState<SortOption>('a-z');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('keepy_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('keepy_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    localStorage.setItem('keepy_branding', JSON.stringify(branding));
  }, [branding]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('keepy_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('keepy_theme', 'light');
    }
  }, [darkMode]);

  // --- Helpers ---
  const sortCategories = (cats: Category[]) => {
    return [...cats].sort((a, b) => {
      if (categorySort === 'a-z') return a.name.localeCompare(b.name);
      if (categorySort === 'z-a') return b.name.localeCompare(a.name);
      // Using ID as proxy for creation time since IDs are Date.now() or sequential
      if (categorySort === 'newest') return b.id.localeCompare(a.id);
      if (categorySort === 'oldest') return a.id.localeCompare(b.id);
      return 0;
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, field: keyof Branding) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setBranding(prev => ({ ...prev, [field]: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       return matchesSearch && matchesCategory;
    });

    return result.sort((a, b) => {
      if (profileSort === 'a-z') return a.username.localeCompare(b.username);
      if (profileSort === 'z-a') return b.username.localeCompare(a.username);
      if (profileSort === 'newest') return b.createdAt - a.createdAt;
      if (profileSort === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, profileSort]);

  // Process categories for display (sorted root, sorted sub)
  const displayCategories = useMemo(() => {
    const root = categories.filter(c => !c.parentId);
    const sortedRoot = sortCategories(root);

    return sortedRoot.map(cat => ({
      ...cat,
      children: sortCategories(categories.filter(sub => sub.parentId === cat.id))
    }));
  }, [categories, categorySort]);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    // Clean username (remove @ and url)
    let cleanUser = newProfileUsername.trim();
    if (cleanUser.includes('instagram.com/')) {
       const parts = cleanUser.split('instagram.com/');
       cleanUser = parts[1].split('/')[0].split('?')[0];
    }
    cleanUser = cleanUser.replace('@', '');

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleDeleteCategory = (id: string) => {
    if (!window.confirm("Are you sure? This will delete the category and uncategorize its profiles. Subcategories will also be deleted.")) {
      return;
    }

    // Identify IDs to remove (parent + children)
    const childrenIds = categories.filter(c => c.parentId === id).map(c => c.id);
    const idsToDelete = [id, ...childrenIds];

    // Remove categories
    setCategories(prev => prev.filter(c => !idsToDelete.includes(c.id)));

    // Reset selection if the currently selected category is deleted
    if (selectedCategoryId && idsToDelete.includes(selectedCategoryId)) {
      setSelectedCategoryId(null);
    }

    // Uncategorize profiles that were in these categories
    setProfiles(prev => prev.map(p => 
       idsToDelete.includes(p.categoryId) ? { ...p, categoryId: '' } : p
    ));
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  // Render Helpers
  const renderLogo = () => {
    const fullLogo = darkMode ? branding.logoDark : branding.logoLight;

    if (fullLogo) {
      return <img src={fullLogo} alt="Keepy" className="h-8 w-auto object-contain" />;
    }

    return (
      <div className="flex items-center gap-2">
         {branding.icon ? (
           <img src={branding.icon} alt="Icon" className="w-8 h-8 object-contain" />
         ) : (
           <Icons.Instagram className="text-pink-500 w-8 h-8" />
         )}
         <span className={`text-2xl font-bold ${branding.icon ? 'text-gray-900 dark:text-white' : 'bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500'}`}>
           Keepy
         </span>
      </div>
    );
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6 h-20 flex items-center">
          {renderLogo()}
        </div>

        <div className="px-4 py-2 space-y-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>

          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-800 rounded-lg p-1.5">
             <Icons.ArrowUpDown className="w-4 h-4 text-gray-400 ml-2" />
             <select 
               value={categorySort}
               onChange={(e) => setCategorySort(e.target.value as SortOption)}
               className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 w-full focus:outline-none cursor-pointer border-none p-0 pr-2"
             >
               <option value="a-z">Name (A-Z)</option>
               <option value="z-a">Name (Z-A)</option>
               <option value="newest">Newest</option>
               <option value="oldest">Oldest</option>
             </select>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {displayCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <div className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors">
                 <button
                  onClick={() => setSelectedCategoryId(cat.id)}
                  className={`flex-1 flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                    selectedCategoryId === cat.id 
                      ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                      : 'text-gray-600 dark:text-slate-400'
                  }`}
                >
                  <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                  <span className="truncate flex-1">{cat.name}</span>
                </button>
                <button 
                   onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat.id); }}
                   className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                   title="Delete Category"
                >
                   <Icons.Trash2 className="w-4 h-4" />
                </button>
               </div>

              {/* Subcategories */}
              {cat.children.map(sub => (
                <div key={sub.id} className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors ml-6">
                    <button
                      onClick={() => setSelectedCategoryId(sub.id)}
                      className={`flex-1 flex items-center gap-3 px-4 py-2 rounded-xl text-left text-sm transition-all ${
                        selectedCategoryId === sub.id 
                          ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                          : 'text-gray-500 dark:text-slate-500'
                      }`}
                    >
                      <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                      <span className="truncate">{sub.name}</span>
                    </button>
                    <button 
                       onClick={(e) => { e.stopPropagation(); handleDeleteCategory(sub.id); }}
                       className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                       title="Delete Subcategory"
                    >
                       <Icons.Trash2 className="w-3.5 h-3.5" />
                    </button>
                </div>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800 space-y-2">
           <button 
             onClick={() => setIsSettingsOpen(true)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             <Icons.Settings className="w-5 h-5" />
             <span>Settings</span>
           </button>
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <div className="flex items-center gap-2">
            {renderLogo()}
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setIsSettingsOpen(true)} className="p-2">
               <Icons.Settings className="w-6 h-6 text-gray-600 dark:text-slate-300" />
            </button>
            <button onClick={() => setDarkMode(!darkMode)} className="p-2">
              {darkMode ? <Icons.Sun className="w-6 h-6 text-gray-600 dark:text-slate-300" /> : <Icons.Moon className="w-6 h-6 text-gray-600 dark:text-slate-300" />}
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire Instagram collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search usernames or notes..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>
              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category Select */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <div className="flex items-center gap-2 px-2">
                   <Icons.ArrowUpDown className="w-4 h-4 text-gray-400" />
                   <select 
                      className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-0"
                      value={profileSort}
                      onChange={(e) => setProfileSort(e.target.value as SortOption)}
                   >
                     <option value="newest">Newest First</option>
                     <option value="oldest">Oldest First</option>
                     <option value="a-z">Username (A-Z)</option>
                     <option value="z-a">Username (Z-A)</option>
                   </select>
                 </div>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Settings Modal */}
      <Modal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} title="App Settings">
        <div className="space-y-6">
          <div className="p-4 bg-gray-50 dark:bg-slate-900 rounded-xl">
             <h4 className="font-semibold mb-2">Custom Branding</h4>
             <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
               Upload your logo files to customize the app appearance.
             </p>

             {/* Icon Upload */}
             <div className="mb-4">
               <label className="block text-sm font-medium mb-1.5">Logo Icon (Symbol)</label>
               <div className="flex items-center gap-4">
                 <div className="w-12 h-12 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg flex items-center justify-center overflow-hidden">
                    {branding.icon ? <img src={branding.icon} className="w-full h-full object-contain p-1" /> : <Icons.Instagram className="text-gray-300" />}
                 </div>
                 <input 
                   type="file" 
                   accept="image/*"
                   className="text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-pink-50 file:text-pink-700 hover:file:bg-pink-100 dark:file:bg-pink-900/20 dark:file:text-pink-300"
                   onChange={(e) => handleFileUpload(e, 'icon')}
                 />
               </div>
             </div>

             {/* Light Mode Logo */}
             <div className="mb-4">
               <label className="block text-sm font-medium mb-1.5">Full Logo (Light Mode)</label>
               <div className="flex items-center gap-4">
                 <div className="h-12 w-32 bg-white border border-gray-200 rounded-lg flex items-center justify-center overflow-hidden">
                    {branding.logoLight ? <img src={branding.logoLight} className="w-full h-full object-contain p-1" /> : <span className="text-xs text-gray-400">Preview</span>}
                 </div>
                 <input 
                   type="file" 
                   accept="image/*"
                   className="text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-gray-50 file:text-gray-700 hover:file:bg-gray-100"
                   onChange={(e) => handleFileUpload(e, 'logoLight')}
                 />
               </div>
             </div>

             {/* Dark Mode Logo */}
             <div>
               <label className="block text-sm font-medium mb-1.5">Full Logo (Dark Mode)</label>
               <div className="flex items-center gap-4">
                 <div className="h-12 w-32 bg-slate-900 border border-slate-700 rounded-lg flex items-center justify-center overflow-hidden">
                    {branding.logoDark ? <img src={branding.logoDark} className="w-full h-full object-contain p-1" /> : <span className="text-xs text-gray-500">Preview</span>}
                 </div>
                 <input 
                   type="file" 
                   accept="image/*"
                   className="text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-gray-50 file:text-gray-700 hover:file:bg-gray-100 dark:file:bg-slate-800 dark:file:text-slate-300"
                   onChange={(e) => handleFileUpload(e, 'logoDark')}
                 />
               </div>
             </div>
          </div>

          <div className="flex justify-end">
             <button 
               onClick={() => setIsSettingsOpen(false)}
               className="px-6 py-2 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold"
             >
               Done
             </button>
          </div>
        </div>
      </Modal>

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Instagram Profile">
         <div className="space-y-4">
           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Instagram Username or URL</label>
             <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">@</span>
                <input 
                  type="text" 
                  className="w-full pl-8 p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all"
                  placeholder="username or paste profile URL"
                  value={newProfileUsername}
                  onChange={(e) => setNewProfileUsername(e.target.value)}
                  autoFocus
                />
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {displayCategories.flatMap(cat => [
                   cat,
                   ...cat.children
                ]).map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {displayCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="w-24 h-24 rounded-full p-[3px] bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 mb-4 shadow-lg">
                <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
                   <Icons.Instagram className="w-10 h-10 text-gray-300" />
                </div>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">@{selectedProfile.username}</h2>
              <div 
                className="mt-2 px-3 py-1 rounded-full text-sm font-medium"
                style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
              >
                {getCategoryName(selectedProfile.categoryId)}
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={`https://instagram.com/${selectedProfile.username}`}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open in Instagram
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// --- CONFIGURATION ---
// Paste your logo URLs or Base64 strings inside the quotes below.
const BRANDING = {
  // The small icon/symbol (used if full logos aren't provided, or for favicon style usage)
  icon: "", 

  // Full logo for Light Mode (e.g., Dark text)
  logoLight: "", 

  // Full logo for Dark Mode (e.g., White text)
  logoDark: "", 
};

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'bonappetit', categoryId: '3', notes: 'Recipe ideas', createdAt: Date.now() - 20000 },
];

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('keepy_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('keepy_profiles');
    return saved ? JSON.parse(saved) : INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('keepy_theme') === 'dark';
    }
    return false;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Sorting State
  const [profileSort, setProfileSort] = useState<SortOption>('newest');
  const [categorySort, setCategorySort] = useState<SortOption>('a-z');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('keepy_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('keepy_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('keepy_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('keepy_theme', 'light');
    }
  }, [darkMode]);

  // --- Helpers ---
  const sortCategories = (cats: Category[]) => {
    return [...cats].sort((a, b) => {
      if (categorySort === 'a-z') return a.name.localeCompare(b.name);
      if (categorySort === 'z-a') return b.name.localeCompare(a.name);
      // Using ID as proxy for creation time since IDs are Date.now() or sequential
      if (categorySort === 'newest') return b.id.localeCompare(a.id);
      if (categorySort === 'oldest') return a.id.localeCompare(b.id);
      return 0;
    });
  };

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       return matchesSearch && matchesCategory;
    });

    return result.sort((a, b) => {
      if (profileSort === 'a-z') return a.username.localeCompare(b.username);
      if (profileSort === 'z-a') return b.username.localeCompare(a.username);
      if (profileSort === 'newest') return b.createdAt - a.createdAt;
      if (profileSort === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, profileSort]);

  // Process categories for display (sorted root, sorted sub)
  const displayCategories = useMemo(() => {
    const root = categories.filter(c => !c.parentId);
    const sortedRoot = sortCategories(root);

    return sortedRoot.map(cat => ({
      ...cat,
      children: sortCategories(categories.filter(sub => sub.parentId === cat.id))
    }));
  }, [categories, categorySort]);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    // Clean username (remove @ and url)
    let cleanUser = newProfileUsername.trim();
    if (cleanUser.includes('instagram.com/')) {
       const parts = cleanUser.split('instagram.com/');
       cleanUser = parts[1].split('/')[0].split('?')[0];
    }
    cleanUser = cleanUser.replace('@', '');

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleDeleteCategory = (id: string) => {
    if (!window.confirm("Are you sure? This will delete the category and uncategorize its profiles. Subcategories will also be deleted.")) {
      return;
    }

    // Identify IDs to remove (parent + children)
    const childrenIds = categories.filter(c => c.parentId === id).map(c => c.id);
    const idsToDelete = [id, ...childrenIds];

    // Remove categories
    setCategories(prev => prev.filter(c => !idsToDelete.includes(c.id)));

    // Reset selection if the currently selected category is deleted
    if (selectedCategoryId && idsToDelete.includes(selectedCategoryId)) {
      setSelectedCategoryId(null);
    }

    // Uncategorize profiles that were in these categories
    setProfiles(prev => prev.map(p => 
       idsToDelete.includes(p.categoryId) ? { ...p, categoryId: '' } : p
    ));
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  // Render Helpers
  const renderLogo = () => {
    // 1. Try to use Full Logos if available
    const fullLogo = darkMode ? BRANDING.logoDark : BRANDING.logoLight;
    if (fullLogo) {
      return <img src={fullLogo} alt="Keepy" className="h-8 w-auto object-contain" />;
    }

    // 2. Fallback to Icon + Text
    return (
      <div className="flex items-center gap-2">
         {BRANDING.icon ? (
           <img src={BRANDING.icon} alt="Icon" className="w-8 h-8 object-contain" />
         ) : (
           <Icons.Instagram className="text-pink-500 w-8 h-8" />
         )}
         <span className={`text-2xl font-bold ${BRANDING.icon ? 'text-gray-900 dark:text-white' : 'bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500'}`}>
           Keepy
         </span>
      </div>
    );
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6 h-20 flex items-center">
          {renderLogo()}
        </div>

        <div className="px-4 py-2 space-y-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>

          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-800 rounded-lg p-1.5">
             <Icons.ArrowUpDown className="w-4 h-4 text-gray-400 ml-2" />
             <select 
               value={categorySort}
               onChange={(e) => setCategorySort(e.target.value as SortOption)}
               className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 w-full focus:outline-none cursor-pointer border-none p-0 pr-2"
             >
               <option value="a-z">Name (A-Z)</option>
               <option value="z-a">Name (Z-A)</option>
               <option value="newest">Newest</option>
               <option value="oldest">Oldest</option>
             </select>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {displayCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <div className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors">
                 <button
                  onClick={() => setSelectedCategoryId(cat.id)}
                  className={`flex-1 flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                    selectedCategoryId === cat.id 
                      ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                      : 'text-gray-600 dark:text-slate-400'
                  }`}
                >
                  <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                  <span className="truncate flex-1">{cat.name}</span>
                </button>
                <button 
                   onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat.id); }}
                   className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                   title="Delete Category"
                >
                   <Icons.Trash2 className="w-4 h-4" />
                </button>
               </div>

              {/* Subcategories */}
              {cat.children.map(sub => (
                <div key={sub.id} className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors ml-6">
                    <button
                      onClick={() => setSelectedCategoryId(sub.id)}
                      className={`flex-1 flex items-center gap-3 px-4 py-2 rounded-xl text-left text-sm transition-all ${
                        selectedCategoryId === sub.id 
                          ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                          : 'text-gray-500 dark:text-slate-500'
                      }`}
                    >
                      <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                      <span className="truncate">{sub.name}</span>
                    </button>
                    <button 
                       onClick={(e) => { e.stopPropagation(); handleDeleteCategory(sub.id); }}
                       className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                       title="Delete Subcategory"
                    >
                       <Icons.Trash2 className="w-3.5 h-3.5" />
                    </button>
                </div>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800 space-y-2">
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <div className="flex items-center gap-2">
            {renderLogo()}
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setDarkMode(!darkMode)} className="p-2">
              {darkMode ? <Icons.Sun className="w-6 h-6 text-gray-600 dark:text-slate-300" /> : <Icons.Moon className="w-6 h-6 text-gray-600 dark:text-slate-300" />}
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire Instagram collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search usernames or notes..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>
              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category Select */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <div className="flex items-center gap-2 px-2">
                   <Icons.ArrowUpDown className="w-4 h-4 text-gray-400" />
                   <select 
                      className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-0"
                      value={profileSort}
                      onChange={(e) => setProfileSort(e.target.value as SortOption)}
                   >
                     <option value="newest">Newest First</option>
                     <option value="oldest">Oldest First</option>
                     <option value="a-z">Username (A-Z)</option>
                     <option value="z-a">Username (Z-A)</option>
                   </select>
                 </div>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Instagram Profile">
         <div className="space-y-4">
           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Instagram Username or URL</label>
             <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">@</span>
                <input 
                  type="text" 
                  className="w-full pl-8 p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all"
                  placeholder="username or paste profile URL"
                  value={newProfileUsername}
                  onChange={(e) => setNewProfileUsername(e.target.value)}
                  autoFocus
                />
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {displayCategories.flatMap(cat => [
                   cat,
                   ...cat.children
                ]).map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {displayCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="w-24 h-24 rounded-full p-[3px] bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 mb-4 shadow-lg">
                <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
                   <Icons.Instagram className="w-10 h-10 text-gray-300" />
                </div>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">@{selectedProfile.username}</h2>
              <div 
                className="mt-2 px-3 py-1 rounded-full text-sm font-medium"
                style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
              >
                {getCategoryName(selectedProfile.categoryId)}
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={`https://instagram.com/${selectedProfile.username}`}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open in Instagram
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// --- CONFIGURATION ---
// Paste your logo URLs or Base64 strings inside the quotes below.
const BRANDING = {
  // The small icon/symbol (used if full logos aren't provided, or for favicon style usage)
  icon: "", 

  // Full logo for Light Mode (e.g., Dark text)
  logoLight: "", 

  // Full logo for Dark Mode (e.g., White text)
  logoDark: "", 
};

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'bonappetit', categoryId: '3', notes: 'Recipe ideas', createdAt: Date.now() - 20000 },
];

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('keepy_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('keepy_profiles');
    return saved ? JSON.parse(saved) : INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('keepy_theme') === 'dark';
    }
    return false;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Sorting State
  const [profileSort, setProfileSort] = useState<SortOption>('newest');
  const [categorySort, setCategorySort] = useState<SortOption>('a-z');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('keepy_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('keepy_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('keepy_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('keepy_theme', 'light');
    }
  }, [darkMode]);

  // --- Helpers ---
  const sortCategories = (cats: Category[]) => {
    return [...cats].sort((a, b) => {
      if (categorySort === 'a-z') return a.name.localeCompare(b.name);
      if (categorySort === 'z-a') return b.name.localeCompare(a.name);
      // Using ID as proxy for creation time since IDs are Date.now() or sequential
      if (categorySort === 'newest') return b.id.localeCompare(a.id);
      if (categorySort === 'oldest') return a.id.localeCompare(b.id);
      return 0;
    });
  };

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       return matchesSearch && matchesCategory;
    });

    return result.sort((a, b) => {
      if (profileSort === 'a-z') return a.username.localeCompare(b.username);
      if (profileSort === 'z-a') return b.username.localeCompare(a.username);
      if (profileSort === 'newest') return b.createdAt - a.createdAt;
      if (profileSort === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, profileSort]);

  // Process categories for display (sorted root, sorted sub)
  const displayCategories = useMemo(() => {
    const root = categories.filter(c => !c.parentId);
    const sortedRoot = sortCategories(root);

    return sortedRoot.map(cat => ({
      ...cat,
      children: sortCategories(categories.filter(sub => sub.parentId === cat.id))
    }));
  }, [categories, categorySort]);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    // Clean username (remove @ and url)
    let cleanUser = newProfileUsername.trim();
    if (cleanUser.includes('instagram.com/')) {
       const parts = cleanUser.split('instagram.com/');
       cleanUser = parts[1].split('/')[0].split('?')[0];
    }
    cleanUser = cleanUser.replace('@', '');

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleDeleteCategory = (id: string) => {
    if (!window.confirm("Are you sure? This will delete the category and uncategorize its profiles. Subcategories will also be deleted.")) {
      return;
    }

    // Identify IDs to remove (parent + children)
    const childrenIds = categories.filter(c => c.parentId === id).map(c => c.id);
    const idsToDelete = [id, ...childrenIds];

    // Remove categories
    setCategories(prev => prev.filter(c => !idsToDelete.includes(c.id)));

    // Reset selection if the currently selected category is deleted
    if (selectedCategoryId && idsToDelete.includes(selectedCategoryId)) {
      setSelectedCategoryId(null);
    }

    // Uncategorize profiles that were in these categories
    setProfiles(prev => prev.map(p => 
       idsToDelete.includes(p.categoryId) ? { ...p, categoryId: '' } : p
    ));
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const handleShare = async () => {
    const title = selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles';
    let text = `📂 ${title} \n(Shared via Keepy)\n\n`;

    const getProfilesForCat = (catId: string) => profiles.filter(p => p.categoryId === catId);

    if (selectedCategoryId) {
      // 1. Root Category Profiles
      const rootProfiles = getProfilesForCat(selectedCategoryId);
      if (rootProfiles.length > 0) {
         text += `${title}:\n`;
         rootProfiles.forEach(p => text += `• instagram.com/${p.username}\n`);
         text += '\n';
      }

      // 2. Subcategories
      const subcats = categories.filter(c => c.parentId === selectedCategoryId);
      subcats.forEach(sub => {
        const subProfiles = getProfilesForCat(sub.id);
        if (subProfiles.length > 0) {
          text += `${sub.name}:\n`;
          subProfiles.forEach(p => text += `• instagram.com/${p.username}\n`);
          text += '\n';
        }
      });
    } else {
      // All Profiles - Grouped by Category
      // Uncategorized
      const uncategorized = profiles.filter(p => !p.categoryId);
      if (uncategorized.length > 0) {
        text += `Uncategorized:\n`;
        uncategorized.forEach(p => text += `• instagram.com/${p.username}\n`);
        text += '\n';
      }

      // Categories
      // sort by name for sharing
      const sortedCats = [...categories].sort((a,b) => a.name.localeCompare(b.name));

      sortedCats.forEach(cat => {
        const catProfiles = getProfilesForCat(cat.id);
        if (catProfiles.length > 0) {
           text += `${cat.name}:\n`;
           catProfiles.forEach(p => text += `• instagram.com/${p.username}\n`);
           text += '\n';
        }
      });
    }

    try {
      if (navigator.share) {
        await navigator.share({
          title: `Keepy List: ${title}`,
          text: text,
        });
      } else {
        await navigator.clipboard.writeText(text);
        alert('List copied to clipboard!');
      }
    } catch (error) {
      console.error('Error sharing', error);
    }
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  // Render Helpers
  const renderLogo = () => {
    // 1. Try to use Full Logos if available
    const fullLogo = darkMode ? BRANDING.logoDark : BRANDING.logoLight;
    if (fullLogo) {
      return <img src={fullLogo} alt="Keepy" className="h-8 w-auto object-contain" />;
    }

    // 2. Fallback to Icon + Text
    return (
      <div className="flex items-center gap-2">
         {BRANDING.icon ? (
           <img src={BRANDING.icon} alt="Icon" className="w-8 h-8 object-contain" />
         ) : (
           <Icons.Instagram className="text-pink-500 w-8 h-8" />
         )}
         <span className={`text-2xl font-bold ${BRANDING.icon ? 'text-gray-900 dark:text-white' : 'bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500'}`}>
           Keepy
         </span>
      </div>
    );
  };

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6 h-20 flex items-center">
          {renderLogo()}
        </div>

        <div className="px-4 py-2 space-y-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>

          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-800 rounded-lg p-1.5">
             <Icons.ArrowUpDown className="w-4 h-4 text-gray-400 ml-2" />
             <select 
               value={categorySort}
               onChange={(e) => setCategorySort(e.target.value as SortOption)}
               className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 w-full focus:outline-none cursor-pointer border-none p-0 pr-2"
             >
               <option value="a-z">Name (A-Z)</option>
               <option value="z-a">Name (Z-A)</option>
               <option value="newest">Newest</option>
               <option value="oldest">Oldest</option>
             </select>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {displayCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <div className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors">
                 <button
                  onClick={() => setSelectedCategoryId(cat.id)}
                  className={`flex-1 flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                    selectedCategoryId === cat.id 
                      ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                      : 'text-gray-600 dark:text-slate-400'
                  }`}
                >
                  <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                  <span className="truncate flex-1">{cat.name}</span>
                </button>
                <button 
                   onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat.id); }}
                   className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                   title="Delete Category"
                >
                   <Icons.Trash2 className="w-4 h-4" />
                </button>
               </div>

              {/* Subcategories */}
              {cat.children.map(sub => (
                <div key={sub.id} className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors ml-6">
                    <button
                      onClick={() => setSelectedCategoryId(sub.id)}
                      className={`flex-1 flex items-center gap-3 px-4 py-2 rounded-xl text-left text-sm transition-all ${
                        selectedCategoryId === sub.id 
                          ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                          : 'text-gray-500 dark:text-slate-500'
                      }`}
                    >
                      <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                      <span className="truncate">{sub.name}</span>
                    </button>
                    <button 
                       onClick={(e) => { e.stopPropagation(); handleDeleteCategory(sub.id); }}
                       className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                       title="Delete Subcategory"
                    >
                       <Icons.Trash2 className="w-3.5 h-3.5" />
                    </button>
                </div>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800 space-y-2">
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <div className="flex items-center gap-2">
            {renderLogo()}
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setDarkMode(!darkMode)} className="p-2">
              {darkMode ? <Icons.Sun className="w-6 h-6 text-gray-600 dark:text-slate-300" /> : <Icons.Moon className="w-6 h-6 text-gray-600 dark:text-slate-300" />}
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                  <button 
                    onClick={handleShare}
                    className="ml-2 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-400 hover:text-pink-500 transition-colors"
                    title="Share this list"
                  >
                    <Icons.Share2 className="w-5 h-5" />
                  </button>
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire Instagram collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search usernames or notes..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>
              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category Select */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <div className="flex items-center gap-2 px-2">
                   <Icons.ArrowUpDown className="w-4 h-4 text-gray-400" />
                   <select 
                      className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-0"
                      value={profileSort}
                      onChange={(e) => setProfileSort(e.target.value as SortOption)}
                   >
                     <option value="newest">Newest First</option>
                     <option value="oldest">Oldest First</option>
                     <option value="a-z">Username (A-Z)</option>
                     <option value="z-a">Username (Z-A)</option>
                   </select>
                 </div>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Instagram Profile">
         <div className="space-y-4">
           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Instagram Username or URL</label>
             <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">@</span>
                <input 
                  type="text" 
                  className="w-full pl-8 p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all"
                  placeholder="username or paste profile URL"
                  value={newProfileUsername}
                  onChange={(e) => setNewProfileUsername(e.target.value)}
                  autoFocus
                />
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {displayCategories.flatMap(cat => [
                   cat,
                   ...cat.children
                ]).map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {displayCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="w-24 h-24 rounded-full p-[3px] bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 mb-4 shadow-lg">
                <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
                   <Icons.Instagram className="w-10 h-10 text-gray-300" />
                </div>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">@{selectedProfile.username}</h2>
              <div 
                className="mt-2 px-3 py-1 rounded-full text-sm font-medium"
                style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
              >
                {getCategoryName(selectedProfile.categoryId)}
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={`https://instagram.com/${selectedProfile.username}`}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open in Instagram
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

export type Platform = 'instagram' | 'facebook' | 'tiktok' | 'twitter' | 'website';

export interface Category {
  id: string;
  name: string;
  color: string;
  parentId?: string; // If undefined, it's a main category. If defined, it's a subcategory.
}

export interface Profile {
  id: string;
  username: string; // For 'website', this is the URL
  platform: Platform;
  categoryId: string;
  notes: string;
  createdAt: number;
}

export type SortOption = 'a-z' | 'z-a' | 'newest' | 'oldest';

export const PASTEL_COLORS = [
  '#FFB3BA', // Red/Pink
  '#FFDFBA', // Orange
  '#FFFFBA', // Yellow
  '#BAFFC9', // Green
  '#BAE1FF', // Blue
  '#E2BAFF', // Purple
  '#F0F0F0', // Gray
  '#C9C9FF', // Indigo
];

import React from 'react';
import { Profile, Category, Platform } from '../types';
import { Icons } from './Icon';

interface ProfileCardProps {
  profile: Profile;
  category?: Category;
  onClick: (profile: Profile) => void;
  onEdit: (e: React.MouseEvent, profile: Profile) => void;
}

const PlatformIcon = ({ platform }: { platform: Platform }) => {
  switch (platform) {
    case 'facebook':
      return (
        <div className="w-12 h-12 rounded-full bg-blue-600 flex-shrink-0 flex items-center justify-center text-white shadow-sm">
          <Icons.Facebook className="w-6 h-6" />
        </div>
      );
    case 'twitter':
      return (
        <div className="w-12 h-12 rounded-full bg-black dark:bg-sky-500 flex-shrink-0 flex items-center justify-center text-white shadow-sm">
          <Icons.Twitter className="w-6 h-6" />
        </div>
      );
    case 'tiktok':
      return (
        <div className="w-12 h-12 rounded-full bg-black flex-shrink-0 flex items-center justify-center text-white shadow-sm border border-gray-800">
          <Icons.Video className="w-6 h-6" />
        </div>
      );
    case 'website':
      return (
        <div className="w-12 h-12 rounded-full bg-emerald-500 flex-shrink-0 flex items-center justify-center text-white shadow-sm">
          <Icons.Globe className="w-6 h-6" />
        </div>
      );
    case 'instagram':
    default:
      return (
        <div className="w-12 h-12 rounded-full bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 p-[2px] flex-shrink-0 shadow-sm">
           <div className="w-full h-full rounded-full bg-white dark:bg-slate-800 flex items-center justify-center">
              <Icons.Instagram className="w-6 h-6 text-gray-900 dark:text-white" />
           </div>
        </div>
      );
  }
};

export const ProfileCard: React.FC<ProfileCardProps> = ({ profile, category, onClick, onEdit }) => {
  const displayTitle = profile.platform === 'website' 
    ? profile.username.replace(/^https?:\/\/(www\.)?/, '').split('/')[0] // Clean display for URL
    : `@${profile.username}`;

  return (
    <div 
      onClick={() => onClick(profile)}
      className="group relative bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 hover:shadow-md hover:-translate-y-1 transition-all cursor-pointer flex items-center gap-4"
    >
      {/* Decorative colored strip based on category */}
      <div 
        className="absolute left-0 top-0 bottom-0 w-1.5 rounded-l-xl" 
        style={{ backgroundColor: category?.color || '#cbd5e1' }}
      />

      <PlatformIcon platform={profile.platform} />

      <div className="flex-1 min-w-0">
        <h3 className="font-semibold text-gray-900 dark:text-white truncate" title={profile.username}>
          {displayTitle}
        </h3>
        <div className="flex items-center gap-2 mt-0.5">
          <span className="text-[10px] uppercase font-bold tracking-wider text-gray-400 dark:text-slate-500">
            {profile.platform}
          </span>
        </div>
        {profile.notes && (
           <p className="text-xs text-gray-500 dark:text-slate-400 truncate mt-1">
             {profile.notes}
           </p>
        )}
      </div>

      <button 
        onClick={(e) => onEdit(e, profile)}
        className="p-2 opacity-0 group-hover:opacity-100 transition-opacity rounded-full hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-500"
      >
        <Icons.MoreVertical className="w-4 h-4" />
      </button>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS, Platform } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// --- CONFIGURATION ---
// Paste your logo URLs or Base64 strings inside the quotes below.
const BRANDING = {
  // The small icon/symbol (used if full logos aren't provided, or for favicon style usage)
  icon: "", 

  // Full logo for Light Mode (e.g., Dark text)
  logoLight: "", 

  // Full logo for Dark Mode (e.g., White text)
  logoDark: "", 
};

// Initial Mock Data
const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Fashion', color: '#FFB3BA' },
  { id: '2', name: 'Tech', color: '#BAE1FF' },
  { id: '3', name: 'Food', color: '#BAFFC9' },
  { id: '4', name: 'Streetwear', color: '#FFDFBA', parentId: '1' }, // Subcategory of Fashion
];

const INITIAL_PROFILES: Profile[] = [
  { id: 'p1', username: 'mkbhd', platform: 'instagram', categoryId: '2', notes: 'Best tech reviews', createdAt: Date.now() },
  { id: 'p2', username: 'hypebeast', platform: 'instagram', categoryId: '4', notes: 'Streetwear news', createdAt: Date.now() - 10000 },
  { id: 'p3', username: 'TheVerge', platform: 'twitter', categoryId: '2', notes: 'Tech news', createdAt: Date.now() - 20000 },
];

export default function App() {
  // --- State ---
  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('keepy_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const saved = localStorage.getItem('keepy_profiles');
    if (saved) {
      // Migration: Ensure 'platform' exists for old data
      const parsed = JSON.parse(saved);
      return parsed.map((p: any) => ({
        ...p,
        platform: p.platform || 'instagram'
      }));
    }
    return INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
       return localStorage.getItem('keepy_theme') === 'dark';
    }
    return false;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Sorting & Filtering State
  const [profileSort, setProfileSort] = useState<SortOption>('newest');
  const [categorySort, setCategorySort] = useState<SortOption>('a-z');
  const [platformFilter, setPlatformFilter] = useState<Platform | 'all'>('all');

  // Modals
  const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedProfile, setSelectedProfile] = useState<Profile | null>(null);

  // Forms
  const [newProfileUsername, setNewProfileUsername] = useState('');
  const [newProfilePlatform, setNewProfilePlatform] = useState<Platform>('instagram');
  const [newProfileNotes, setNewProfileNotes] = useState('');
  const [newProfileCategory, setNewProfileCategory] = useState('');

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PASTEL_COLORS[0]);
  const [newCategoryParent, setNewCategoryParent] = useState<string>('');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('keepy_categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('keepy_profiles', JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('keepy_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('keepy_theme', 'light');
    }
  }, [darkMode]);

  // --- Helpers ---
  const sortCategories = (cats: Category[]) => {
    return [...cats].sort((a, b) => {
      if (categorySort === 'a-z') return a.name.localeCompare(b.name);
      if (categorySort === 'z-a') return b.name.localeCompare(a.name);
      // Using ID as proxy for creation time since IDs are Date.now() or sequential
      if (categorySort === 'newest') return b.id.localeCompare(a.id);
      if (categorySort === 'oldest') return a.id.localeCompare(b.id);
      return 0;
    });
  };

  const getProfileLink = (profile: Profile) => {
    switch (profile.platform) {
      case 'instagram': return `https://instagram.com/${profile.username}`;
      case 'facebook': return `https://facebook.com/${profile.username}`;
      case 'twitter': return `https://twitter.com/${profile.username}`;
      case 'tiktok': return `https://tiktok.com/@${profile.username.replace('@', '')}`;
      case 'website': return profile.username.startsWith('http') ? profile.username : `https://${profile.username}`;
      default: return '#';
    }
  };

  const cleanInputForPlatform = (input: string, platform: Platform): string => {
    let clean = input.trim();
    if (platform === 'website') return clean; // Keep websites as is

    // Remove URL parts for social platforms if pasted as full URL
    if (clean.includes('instagram.com/')) clean = clean.split('instagram.com/')[1].split('/')[0].split('?')[0];
    else if (clean.includes('facebook.com/')) clean = clean.split('facebook.com/')[1].split('/')[0].split('?')[0];
    else if (clean.includes('twitter.com/')) clean = clean.split('twitter.com/')[1].split('/')[0].split('?')[0];
    else if (clean.includes('x.com/')) clean = clean.split('x.com/')[1].split('/')[0].split('?')[0];
    else if (clean.includes('tiktok.com/@')) clean = clean.split('tiktok.com/@')[1].split('/')[0].split('?')[0];
    else if (clean.includes('tiktok.com/')) clean = clean.split('tiktok.com/')[1].split('/')[0].split('?')[0];

    return clean.replace('@', '');
  };

  // Auto-detect platform from pasted URL
  const handleProfileInput = (value: string) => {
    setNewProfileUsername(value);

    // Simple heuristics
    if (value.includes('instagram.com')) setNewProfilePlatform('instagram');
    else if (value.includes('facebook.com')) setNewProfilePlatform('facebook');
    else if (value.includes('twitter.com') || value.includes('x.com')) setNewProfilePlatform('twitter');
    else if (value.includes('tiktok.com')) setNewProfilePlatform('tiktok');
    // If it looks like a generic URL and platform is default, maybe switch to website?
    // Keeping it simple: user manually selects website if they want.
  };

  // --- Computed ---
  const filteredProfiles = useMemo(() => {
    let result = profiles.filter(p => {
       const matchesSearch = p.username.toLowerCase().includes(searchQuery.toLowerCase()) || 
                             p.notes.toLowerCase().includes(searchQuery.toLowerCase());

       let matchesCategory = true;
       if (selectedCategoryId) {
          // Include direct children and subcategory children
          const subCategoryIds = categories
            .filter(c => c.parentId === selectedCategoryId)
            .map(c => c.id);

          matchesCategory = p.categoryId === selectedCategoryId || subCategoryIds.includes(p.categoryId);
       }

       let matchesPlatform = true;
       if (platformFilter !== 'all') {
         matchesPlatform = p.platform === platformFilter;
       }

       return matchesSearch && matchesCategory && matchesPlatform;
    });

    return result.sort((a, b) => {
      if (profileSort === 'a-z') return a.username.localeCompare(b.username);
      if (profileSort === 'z-a') return b.username.localeCompare(a.username);
      if (profileSort === 'newest') return b.createdAt - a.createdAt;
      if (profileSort === 'oldest') return a.createdAt - b.createdAt;
      return 0;
    });
  }, [profiles, searchQuery, selectedCategoryId, categories, profileSort, platformFilter]);

  // Process categories for display (sorted root, sorted sub)
  const displayCategories = useMemo(() => {
    const root = categories.filter(c => !c.parentId);
    const sortedRoot = sortCategories(root);

    return sortedRoot.map(cat => ({
      ...cat,
      children: sortCategories(categories.filter(sub => sub.parentId === cat.id))
    }));
  }, [categories, categorySort]);

  // --- Handlers ---
  const handleAddProfile = () => {
    if (!newProfileUsername || !newProfileCategory) return;

    const cleanUser = cleanInputForPlatform(newProfileUsername, newProfilePlatform);

    const newProfile: Profile = {
      id: Date.now().toString(),
      username: cleanUser,
      platform: newProfilePlatform,
      categoryId: newProfileCategory,
      notes: newProfileNotes,
      createdAt: Date.now(),
    };

    setProfiles([newProfile, ...profiles]);
    setIsAddProfileOpen(false);
    resetProfileForm();
  };

  const resetProfileForm = () => {
    setNewProfileUsername('');
    setNewProfileNotes('');
    setNewProfileCategory('');
    setNewProfilePlatform('instagram');
  };

  const handleAddCategory = () => {
    if (!newCategoryName) return;
    const newCategory: Category = {
      id: Date.now().toString(),
      name: newCategoryName,
      color: newCategoryColor,
      parentId: newCategoryParent || undefined,
    };
    setCategories([...categories, newCategory]);
    setIsAddCategoryOpen(false);
    setNewCategoryName('');
    setNewCategoryParent('');
  };

  const handleDeleteProfile = (id: string) => {
    setProfiles(profiles.filter(p => p.id !== id));
    setIsPreviewOpen(false);
  };

  const handleDeleteCategory = (id: string) => {
    if (!window.confirm("Are you sure? This will delete the category and uncategorize its profiles. Subcategories will also be deleted.")) {
      return;
    }

    // Identify IDs to remove (parent + children)
    const childrenIds = categories.filter(c => c.parentId === id).map(c => c.id);
    const idsToDelete = [id, ...childrenIds];

    // Remove categories
    setCategories(prev => prev.filter(c => !idsToDelete.includes(c.id)));

    // Reset selection if the currently selected category is deleted
    if (selectedCategoryId && idsToDelete.includes(selectedCategoryId)) {
      setSelectedCategoryId(null);
    }

    // Uncategorize profiles that were in these categories
    setProfiles(prev => prev.map(p => 
       idsToDelete.includes(p.categoryId) ? { ...p, categoryId: '' } : p
    ));
  };

  const handleOpenPreview = (profile: Profile) => {
    setSelectedProfile(profile);
    setIsPreviewOpen(true);
  };

  const handleShare = async () => {
    const title = selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles';
    let text = `📂 ${title} \n(Shared via Keepy)\n\n`;

    // Filter profiles by current platform filter as well
    const profilesToShare = filteredProfiles; // Uses current view state

    // Helper to group by category for the text output
    const groupByCat: Record<string, Profile[]> = {};
    profilesToShare.forEach(p => {
      const catId = p.categoryId;
      if (!groupByCat[catId]) groupByCat[catId] = [];
      groupByCat[catId].push(p);
    });

    const categoriesToPrint = [...categories].sort((a,b) => a.name.localeCompare(b.name));

    // Helper to format line
    const formatLine = (p: Profile) => {
      const link = getProfileLink(p);
      const label = p.platform === 'website' ? 'Web' : p.platform.charAt(0).toUpperCase() + p.platform.slice(1);
      return `• [${label}] ${link}`;
    };

    // 1. Uncategorized (if any in current filter)
    const uncategorized = profilesToShare.filter(p => !p.categoryId);
    if (uncategorized.length > 0) {
      text += `Uncategorized:\n`;
      uncategorized.forEach(p => text += `${formatLine(p)}\n`);
      text += '\n';
    }

    // 2. Categories
    categoriesToPrint.forEach(cat => {
      // Check if this category has profiles in our filtered list
      const catProfiles = profilesToShare.filter(p => p.categoryId === cat.id);
      if (catProfiles.length > 0) {
        text += `${cat.name}:\n`;
        catProfiles.forEach(p => text += `${formatLine(p)}\n`);
        text += '\n';
      }
    });

    try {
      if (navigator.share) {
        await navigator.share({
          title: `Keepy List: ${title}`,
          text: text,
        });
      } else {
        await navigator.clipboard.writeText(text);
        alert('List copied to clipboard!');
      }
    } catch (error) {
      console.error('Error sharing', error);
    }
  };

  const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'Uncategorized';
  const getCategoryColor = (id: string) => categories.find(c => c.id === id)?.color || '#e2e8f0';

  // Render Helpers
  const renderLogo = () => {
    // 1. Try to use Full Logos if available
    const fullLogo = darkMode ? BRANDING.logoDark : BRANDING.logoLight;
    if (fullLogo) {
      return <img src={fullLogo} alt="Keepy" className="h-8 w-auto object-contain" />;
    }

    // 2. Fallback to Icon + Text
    return (
      <div className="flex items-center gap-2">
         {BRANDING.icon ? (
           <img src={BRANDING.icon} alt="Icon" className="w-8 h-8 object-contain" />
         ) : (
           <Icons.Instagram className="text-pink-500 w-8 h-8" />
         )}
         <span className={`text-2xl font-bold ${BRANDING.icon ? 'text-gray-900 dark:text-white' : 'bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-violet-500'}`}>
           Keepy
         </span>
      </div>
    );
  };

  const PLATFORMS: { id: Platform, label: string, icon: React.ReactNode }[] = [
    { id: 'instagram', label: 'Instagram', icon: <Icons.Instagram className="w-4 h-4" /> },
    { id: 'facebook', label: 'Facebook', icon: <Icons.Facebook className="w-4 h-4" /> },
    { id: 'twitter', label: 'Twitter', icon: <Icons.Twitter className="w-4 h-4" /> },
    { id: 'tiktok', label: 'TikTok', icon: <Icons.Video className="w-4 h-4" /> },
    { id: 'website', label: 'Website', icon: <Icons.Globe className="w-4 h-4" /> },
  ];

  return (
    <div className="flex h-screen overflow-hidden">
      {/* --- Sidebar --- */}
      <aside className="w-64 bg-white dark:bg-slate-900 border-r border-gray-200 dark:border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6 h-20 flex items-center">
          {renderLogo()}
        </div>

        <div className="px-4 py-2 space-y-2">
          <button 
            onClick={() => setIsAddCategoryOpen(true)}
            className="w-full py-2 px-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 text-gray-500 dark:text-slate-400 hover:border-pink-400 hover:text-pink-500 transition-colors flex items-center justify-center gap-2 font-medium text-sm"
          >
            <Icons.Plus className="w-4 h-4" /> New Category
          </button>

          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-800 rounded-lg p-1.5">
             <Icons.ArrowUpDown className="w-4 h-4 text-gray-400 ml-2" />
             <select 
               value={categorySort}
               onChange={(e) => setCategorySort(e.target.value as SortOption)}
               className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 w-full focus:outline-none cursor-pointer border-none p-0 pr-2"
             >
               <option value="a-z">Name (A-Z)</option>
               <option value="z-a">Name (Z-A)</option>
               <option value="newest">Newest</option>
               <option value="oldest">Oldest</option>
             </select>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
          <button
            onClick={() => setSelectedCategoryId(null)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
              selectedCategoryId === null 
                ? 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-white font-semibold' 
                : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800/50'
            }`}
          >
            <Icons.FolderOpen className="w-5 h-5" />
            All Profiles
          </button>

          {displayCategories.map(cat => (
            <div key={cat.id} className="space-y-1">
               <div className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors">
                 <button
                  onClick={() => setSelectedCategoryId(cat.id)}
                  className={`flex-1 flex items-center gap-3 px-4 py-2.5 rounded-xl text-left transition-all ${
                    selectedCategoryId === cat.id 
                      ? 'bg-gray-100 dark:bg-slate-800 font-semibold' 
                      : 'text-gray-600 dark:text-slate-400'
                  }`}
                >
                  <span className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></span>
                  <span className="truncate flex-1">{cat.name}</span>
                </button>
                <button 
                   onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat.id); }}
                   className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                   title="Delete Category"
                >
                   <Icons.Trash2 className="w-4 h-4" />
                </button>
               </div>

              {/* Subcategories */}
              {cat.children.map(sub => (
                <div key={sub.id} className="group flex items-center pr-2 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors ml-6">
                    <button
                      onClick={() => setSelectedCategoryId(sub.id)}
                      className={`flex-1 flex items-center gap-3 px-4 py-2 rounded-xl text-left text-sm transition-all ${
                        selectedCategoryId === sub.id 
                          ? 'bg-gray-50 dark:bg-slate-800/50 text-gray-900 dark:text-white font-medium' 
                          : 'text-gray-500 dark:text-slate-500'
                      }`}
                    >
                      <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: sub.color }}></div>
                      <span className="truncate">{sub.name}</span>
                    </button>
                    <button 
                       onClick={(e) => { e.stopPropagation(); handleDeleteCategory(sub.id); }}
                       className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                       title="Delete Subcategory"
                    >
                       <Icons.Trash2 className="w-3.5 h-3.5" />
                    </button>
                </div>
              ))}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-slate-800 space-y-2">
           <button 
             onClick={() => setDarkMode(!darkMode)}
             className="flex items-center gap-3 text-gray-600 dark:text-slate-400 hover:text-gray-900 dark:hover:text-white transition-colors w-full px-4 py-2 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800"
           >
             {darkMode ? <Icons.Sun className="w-5 h-5" /> : <Icons.Moon className="w-5 h-5" />}
             <span>{darkMode ? 'Light Mode' : 'Dark Mode'}</span>
           </button>
        </div>
      </aside>

      {/* --- Main Content --- */}
      <main className="flex-1 flex flex-col h-full bg-white/50 dark:bg-black/20">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 border-b border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          <div className="flex items-center gap-2">
            {renderLogo()}
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setDarkMode(!darkMode)} className="p-2">
              {darkMode ? <Icons.Sun className="w-6 h-6 text-gray-600 dark:text-slate-300" /> : <Icons.Moon className="w-6 h-6 text-gray-600 dark:text-slate-300" />}
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <header className="p-4 md:p-8 pb-0 max-w-7xl mx-auto w-full">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
              <div>
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                  {selectedCategoryId ? getCategoryName(selectedCategoryId) : 'All Profiles'}
                  {selectedCategoryId && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500">
                       {filteredProfiles.length}
                    </span>
                  )}
                  <button 
                    onClick={handleShare}
                    className="ml-2 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-400 hover:text-pink-500 transition-colors"
                    title="Share this list"
                  >
                    <Icons.Share2 className="w-5 h-5" />
                  </button>
                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1">
                  {selectedCategoryId 
                    ? `Manage your ${getCategoryName(selectedCategoryId)} collection` 
                    : 'Your entire collection in one place'}
                </p>
              </div>
              <button 
                onClick={() => setIsAddProfileOpen(true)}
                className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 dark:hover:bg-gray-100 px-6 py-3 rounded-xl font-semibold shadow-lg shadow-gray-200/50 dark:shadow-none flex items-center gap-2 transition-all active:scale-95"
              >
                <Icons.Plus className="w-5 h-5" />
                Add Profile
              </button>
           </div>

           {/* Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search..." 
                  className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>

              {/* Platform Filter */}
              <div className="flex items-center gap-2 px-2 border-r border-gray-200 dark:border-slate-700 hidden sm:flex">
                 <Icons.Filter className="w-4 h-4 text-gray-400" />
                 <select
                   value={platformFilter}
                   onChange={(e) => setPlatformFilter(e.target.value as Platform | 'all')}
                   className="bg-transparent text-sm font-medium text-gray-600 dark:text-gray-300 focus:outline-none cursor-pointer border-none p-0 pr-2"
                 >
                   <option value="all">All Platforms</option>
                   <option value="instagram">Instagram</option>
                   <option value="facebook">Facebook</option>
                   <option value="twitter">Twitter</option>
                   <option value="tiktok">TikTok</option>
                   <option value="website">Websites</option>
                 </select>
              </div>

              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                 {/* Mobile Category & Platform Selects */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1"
                    onChange={(e) => setSelectedCategoryId(e.target.value || null)}
                    value={selectedCategoryId || ''}
                 >
                    <option value="">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>

                 <select
                   value={platformFilter}
                   onChange={(e) => setPlatformFilter(e.target.value as Platform | 'all')}
                   className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1"
                 >
                   <option value="all">All Platforms</option>
                   <option value="instagram">Instagram</option>
                   <option value="facebook">Facebook</option>
                   <option value="twitter">Twitter</option>
                   <option value="tiktok">TikTok</option>
                   <option value="website">Web</option>
                 </select>

                 <div className="flex items-center gap-2 px-2">
                   <Icons.ArrowUpDown className="w-4 h-4 text-gray-400" />
                   <select 
                      className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 cursor-pointer focus:ring-0"
                      value={profileSort}
                      onChange={(e) => setProfileSort(e.target.value as SortOption)}
                   >
                     <option value="newest">Newest</option>
                     <option value="oldest">Oldest</option>
                     <option value="a-z">Name (A-Z)</option>
                     <option value="z-a">Name (Z-A)</option>
                   </select>
                 </div>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
           <div className="max-w-7xl mx-auto">
             {filteredProfiles.length === 0 ? (
               <div className="text-center py-20 opacity-50">
                 <div className="bg-gray-100 dark:bg-slate-800 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Search className="w-10 h-10 text-gray-400" />
                 </div>
                 <h3 className="text-lg font-medium">No profiles found</h3>
                 <p className="text-sm">Try adding one or changing filters</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                 {filteredProfiles.map(profile => (
                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleOpenPreview(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
      </main>

      {/* --- Modals --- */}

      {/* Add Profile Modal */}
      <Modal isOpen={isAddProfileOpen} onClose={() => setIsAddProfileOpen(false)} title="Add Profile">
         <div className="space-y-4">

           {/* Platform Selector */}
           <div>
             <label className="block text-sm font-medium mb-2 text-gray-700 dark:text-gray-300">Select Platform</label>
             <div className="flex gap-2">
               {PLATFORMS.map(p => (
                 <button
                   key={p.id}
                   onClick={() => setNewProfilePlatform(p.id)}
                   className={`flex-1 flex flex-col items-center justify-center p-2 rounded-xl border transition-all ${
                     newProfilePlatform === p.id
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-600 dark:text-pink-300'
                       : 'border-gray-200 dark:border-slate-700 text-gray-500 hover:border-gray-300'
                   }`}
                 >
                   {p.icon}
                   <span className="text-[10px] mt-1 font-medium">{p.label}</span>
                 </button>
               ))}
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                {newProfilePlatform === 'website' ? 'Website URL' : 'Username or Profile URL'}
             </label>
             <div className="relative">
                {newProfilePlatform !== 'website' && (
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 font-mono text-sm">@</span>
                )}
                <input 
                  type="text" 
                  className={`w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all ${newProfilePlatform !== 'website' ? 'pl-8' : ''}`}
                  placeholder={newProfilePlatform === 'website' ? 'https://example.com' : 'username'}
                  value={newProfileUsername}
                  onChange={(e) => handleProfileInput(e.target.value)}
                  autoFocus
                />
             </div>
             {newProfilePlatform !== 'website' && (
               <p className="text-xs text-gray-400 mt-1 ml-1">Paste a full URL to auto-detect platform</p>
             )}
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category</label>
             <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {displayCategories.flatMap(cat => [
                   cat,
                   ...cat.children
                ]).map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setNewProfileCategory(cat.id)}
                    className={`p-2 rounded-lg border text-left text-sm flex items-center gap-2 transition-all ${
                       newProfileCategory === cat.id 
                       ? 'border-pink-500 bg-pink-50 dark:bg-pink-900/20 text-pink-700 dark:text-pink-300 ring-1 ring-pink-500' 
                       : 'border-gray-200 dark:border-slate-700 hover:border-gray-300 dark:hover:border-slate-600'
                    }`}
                  >
                    <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: cat.color }}></div>
                    <span className="truncate">{cat.name}</span>
                  </button>
                ))}
                <button 
                  onClick={() => { setIsAddProfileOpen(false); setIsAddCategoryOpen(true); }}
                  className="p-2 rounded-lg border border-dashed border-gray-300 dark:border-slate-600 text-gray-500 hover:text-pink-500 hover:border-pink-400 flex items-center justify-center gap-1 text-sm"
                >
                  <Icons.Plus className="w-3 h-3" /> New
                </button>
             </div>
           </div>

           <div>
             <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Notes</label>
             <textarea 
               className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all h-24 resize-none"
               placeholder="Why do you follow them? What do you like?"
               value={newProfileNotes}
               onChange={(e) => setNewProfileNotes(e.target.value)}
             />
           </div>

           <button 
             onClick={handleAddProfile}
             disabled={!newProfileUsername || !newProfileCategory}
             className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-xl font-bold shadow-lg shadow-pink-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
           >
             Save Profile
           </button>
         </div>
      </Modal>

      {/* Add Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => setIsAddCategoryOpen(false)} title="New Category">
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Category Name</label>
               <input 
                  type="text" 
                  className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                  placeholder="e.g. Travel, Art, Fitness"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                />
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Color</label>
               <div className="flex flex-wrap gap-3 mb-3">
                 {PASTEL_COLORS.map(color => (
                   <button
                     key={color}
                     onClick={() => setNewCategoryColor(color)}
                     className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${newCategoryColor === color ? 'border-gray-900 dark:border-white scale-110 ring-2 ring-offset-2 ring-gray-200 dark:ring-slate-700' : 'border-transparent'}`}
                     style={{ backgroundColor: color }}
                   />
                 ))}
                 <div className="relative w-8 h-8 overflow-hidden rounded-full border-2 border-gray-200 dark:border-slate-700">
                    <input 
                      type="color" 
                      className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer"
                      value={newCategoryColor}
                      onChange={(e) => setNewCategoryColor(e.target.value)}
                    />
                 </div>
               </div>
             </div>

             <div>
               <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Parent Category (Optional)</label>
               <select 
                 className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 focus:ring-2 focus:ring-pink-500 outline-none"
                 value={newCategoryParent}
                 onChange={(e) => setNewCategoryParent(e.target.value)}
               >
                 <option value="">None (Top Level)</option>
                 {displayCategories.map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             <button 
               onClick={handleAddCategory}
               disabled={!newCategoryName}
               className="w-full py-3 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold hover:opacity-90 transition-all"
             >
               Create Category
             </button>
          </div>
      </Modal>

      {/* Profile Preview/Details Modal */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Profile Details">
           <div className="flex flex-col items-center mb-6">
              <div className="mb-4">
                 {/* Re-use icon logic from ProfileCard logic but bigger */}
                 {(() => {
                    const platform = selectedProfile.platform;
                    if (platform === 'facebook') return <div className="w-24 h-24 rounded-full bg-blue-600 flex items-center justify-center"><Icons.Facebook className="w-12 h-12 text-white" /></div>;
                    if (platform === 'twitter') return <div className="w-24 h-24 rounded-full bg-black dark:bg-sky-500 flex items-center justify-center"><Icons.Twitter className="w-12 h-12 text-white" /></div>;
                    if (platform === 'tiktok') return <div className="w-24 h-24 rounded-full bg-black flex items-center justify-center border border-gray-800"><Icons.Video className="w-12 h-12 text-white" /></div>;
                    if (platform === 'website') return <div className="w-24 h-24 rounded-full bg-emerald-500 flex items-center justify-center"><Icons.Globe className="w-12 h-12 text-white" /></div>;
                    return <div className="w-24 h-24 rounded-full bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 p-1 flex items-center justify-center"><div className="w-full h-full bg-white dark:bg-slate-800 rounded-full flex items-center justify-center"><Icons.Instagram className="w-12 h-12 text-gray-900 dark:text-white" /></div></div>;
                 })()}
              </div>

              <h2 className="text-2xl font-bold text-gray-900 dark:text-white text-center break-all">
                {selectedProfile.platform === 'website' ? selectedProfile.username : `@${selectedProfile.username}`}
              </h2>
              <div className="flex gap-2 items-center mt-2">
                <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-gray-100 dark:bg-slate-700 text-gray-500">
                  {selectedProfile.platform}
                </span>
                <div 
                  className="px-3 py-1 rounded-full text-sm font-medium"
                  style={{ backgroundColor: getCategoryColor(selectedProfile.categoryId) }}
                >
                  {getCategoryName(selectedProfile.categoryId)}
                </div>
              </div>
           </div>

           <div className="bg-gray-50 dark:bg-slate-900 p-4 rounded-xl mb-6">
             <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Notes</h4>
             <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
               {selectedProfile.notes || "No notes added yet."}
             </p>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <a 
                href={getProfileLink(selectedProfile)}
                target="_blank"
                rel="noreferrer"
                className="col-span-2 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <Icons.ExternalLink className="w-4 h-4" />
                Open {selectedProfile.platform === 'website' ? 'Link' : 'Profile'}
              </a>

              <button 
                className="py-2.5 bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 text-gray-900 dark:text-white rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
                onClick={() => {
                   // Pre-fill edit form logic would go here
                   alert("Edit functionality would open form with pre-filled data.");
                }}
              >
                <Icons.Edit2 className="w-4 h-4" /> Edit
              </button>

              <button 
                onClick={() => handleDeleteProfile(selectedProfile.id)}
                className="py-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-400 rounded-xl font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Icons.Trash2 className="w-4 h-4" /> Delete
              </button>
           </div>

           <div className="text-center mt-6">
             <p className="text-xs text-gray-400">
               Added {new Date(selectedProfile.createdAt).toLocaleDateString()}
             </p>
           </div>
        </Modal>
      )}

    </div>
  );
}

