            </button>
            <button onClick={handleLogout} className="p-2 text-gray-500 dark:text-slate-400 hover:text-red-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-lg">
              <Icons.Lock className="w-6 h-6" />
            </button>
