              <button 
                onClick={() => setIsManageCategoriesOpen(false)}
                className="p-2 -ml-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-full transition-colors"
              >
                 <Icons.ArrowLeft className="w-6 h-6 text-gray-900 dark:text-white" />
