                                {c.children.map(sub => (
                                    <div key={sub.id} onClick={() => setNewProfileCategory(sub.id)} className={`ml-6 mt-1 flex items-center gap-2 p-2 rounded-lg border cursor-pointer ${newProfileCategory === sub.id ? 'border-pink-500 bg-pink-50' : 'border-gray-200'}`}>
                                        <div className="w-2 h-2 rounded-full" style={{backgroundColor: sub.color}}></div>
                                        <span className="text-xs">{sub.name}</span>
