                  {(selectedCategoryId || selectedFolderId) && (
                    <span className="text-sm font-normal px-3 py-1 rounded-full bg-gray-100 dark:bg-slate-800 text-gray-500 flex-shrink-0">
                       {filteredProfiles.length}
