                 <select className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" onChange={(e) => handleSelectFolder(e.target.value || null)} value={selectedFolderId || ''}>
                    <option value="">All Folders</option>
                    {folders.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                 </select>

