                </h2>
                <p className="text-gray-500 dark:text-slate-400 mt-1 truncate">
                  {selectedCategoryId || selectedFolderId ? 'Filtered collection view' : 'Your entire collection in one place'}
                </p>
              </div>
              <button onClick={() => { resetProfileForm(); setIsAddProfileOpen(true); }} className="w-full md:w-auto bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-800 px-6 py-3 rounded-xl font-semibold shadow-lg flex items-center justify-center gap-2 active:scale-95 flex-shrink-0">
                <Icons.Plus className="w-5 h-5" /> Add Profile
              </button>
           </div>

           {/* Search & Filters */}
           <div className="flex flex-col sm:flex-row gap-3 items-center bg-white dark:bg-slate-800 p-2 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm overflow-hidden">
              <div className="relative flex-1 w-full">
                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input type="text" placeholder="Search..." className="w-full pl-10 pr-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-400 min-w-0" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              </div>
              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>

              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar min-w-0">
                 {/* 1. FOLDER FILTER */}
                 <select className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" onChange={(e) => handleSelectFolder(e.target.value || null)} value={selectedFolderId || ''}>
                    <option value="">All Folders</option>
                    {folders.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                 </select>

                 {/* 2. PARENT CATEGORY FILTER (Filtered by Folder) */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" 
                    onChange={(e) => handleSelectCategory(e.target.value || null)} 
                    value={activeParentId || ''}
                 >
                    <option value="">All Categories</option>
                    {dropdownParents.map(c => (
                        <option key={c.id} value={c.id}>{c.name}</option>
                    ))}
                 </select>

                 {/* 3. SUB CATEGORY FILTER (Filtered by Parent) */}
                 {activeParentId && dropdownSubs.length > 0 && (
                     <select 
                        className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" 
                        onChange={(e) => handleSelectCategory(e.target.value)} 
                        value={activeSubId || activeParentId} // Use parent ID if sub not selected
                     >
                        <option value={activeParentId}>All in {categories.find(c => c.id === activeParentId)?.name}</option>
                        {dropdownSubs.map(s => (
                            <option key={s.id} value={s.id}>{s.name}</option>
                        ))}
                     </select>
                 )}

                 <select value={platformFilter} onChange={(e) => setPlatformFilter(e.target.value as Platform | 'all')} className="bg-gray-50 dark:bg-slate-700 sm:bg-transparent border-none rounded-lg text-sm px-3 py-2 flex-1 sm:flex-none">
                   <option value="all">Platforms</option>
                   <option value="instagram">Instagram</option>
                   <option value="facebook">Facebook</option>
                   <option value="x">X</option>
                   <option value="tiktok">TikTok</option>
                   <option value="website">Web</option>
                 </select>
              </div>
           </div>
        </header>

        {/* List */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
