                   <ProfileCard 
                     key={profile.id} 
                     profile={profile} 
                     category={categories.find(c => c.id === profile.categoryId)}
                     onClick={handleOpenPreview}
                     onEdit={(e, p) => { e.stopPropagation(); handleStartEdit(p); }}
                   />
                 ))}
               </div>
             )}
           </div>
        </div>
