                       <button key={color} onClick={() => setNewCategoryColor(color)} className={`w-8 h-8 rounded-full border-2 ${newCategoryColor === color ? 'border-gray-900 scale-110' : 'border-transparent'}`} style={{ backgroundColor: color }} />
                     ))}
                   </div>
                 </div>
