                 <option value="">None (Top Level)</option>
                 {categories.filter(c => !c.parentId && c.id !== editingCategoryId).map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             {/* Folder Selection (Required if Top Level) */}
             {!newCategoryParent && (
                 <div>
                    <label className="block text-sm font-medium mb-1">Folder <span className="text-red-500">*</span></label>
                    <select 
