              <div className="flex items-center gap-3">
                  <button onClick={() => setIsManageCategoriesOpen(false)} className="p-2 -ml-2 rounded-full"><Icons.ArrowLeft className="w-6 h-6" /></button>
                  <h2 className="text-xl font-bold">Manage</h2>
              </div>
