               <label className="block text-sm font-medium mb-1">Category Name</label>
               <input type="text" className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 outline-none" value={newCategoryName} onChange={(e) => setNewCategoryName(e.target.value)} />
             </div>
             {!newCategoryParent && (
                 <div>
                   <label className="block text-sm font-medium mb-1">Color</label>
                   <div className="flex flex-wrap gap-2">
                     {PASTEL_COLORS.map(color => (
                       <button key={color} onClick={() => setNewCategoryColor(color)} className={`w-8 h-8 rounded-full border-2 ${newCategoryColor === color ? 'border-gray-900 scale-110' : 'border-transparent'}`} style={{ backgroundColor: color }} />
                     ))}
                   </div>
                 </div>
             )}

             {/* Parent Selection */}
             <div>
               <label className="block text-sm font-medium mb-1">Parent Category (Optional)</label>
               <select className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 outline-none" value={newCategoryParent} onChange={(e) => setNewCategoryParent(e.target.value)} disabled={!!editingCategoryId && categories.some(c => c.parentId === editingCategoryId)}>
                 <option value="">None (Top Level)</option>
