              <div className="h-6 w-[1px] bg-gray-200 dark:bg-slate-700 hidden sm:block"></div>

              <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar min-w-0">
