                 <select className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" onChange={(e) => handleSelectFolder(e.target.value || null)} value={selectedFolderId || ''}>
                    <option value="">All Folders</option>
                    {folders.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                 </select>

                 {/* 2. PARENT CATEGORY FILTER (Filtered by Folder) */}
                 <select 
                    className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" 
                    onChange={(e) => handleSelectCategory(e.target.value || null)} 
                    value={activeParentId || ''}
                 >
                    <option value="">All Categories</option>
                    {dropdownParents.map(c => (
                        <option key={c.id} value={c.id}>{c.name}</option>
                    ))}
                 </select>

                 {/* 3. SUB CATEGORY FILTER (Filtered by Parent) */}
                 {activeParentId && dropdownSubs.length > 0 && (
                     <select 
                        className="md:hidden bg-gray-50 dark:bg-slate-700 border-none rounded-lg text-sm px-3 py-2 flex-1 min-w-[120px]" 
                        onChange={(e) => handleSelectCategory(e.target.value)} 
                        value={activeSubId || activeParentId} // Use parent ID if sub not selected
                     >
                        <option value={activeParentId}>All in {categories.find(c => c.id === activeParentId)?.name}</option>
                        {dropdownSubs.map(s => (
                            <option key={s.id} value={s.id}>{s.name}</option>
                        ))}
                     </select>
                 )}

                 {/* 4. PROFILE SORT */}
                 <select value={profileSort} onChange={(e) => setProfileSort(e.target.value as SortOption)} className="bg-gray-50 dark:bg-slate-700 sm:bg-transparent border-none rounded-lg text-sm px-3 py-2 flex-1 sm:flex-none">
                    <option value="newest">Newest</option>
                    <option value="oldest">Oldest</option>
                    <option value="a-z">A-Z</option>
                    <option value="z-a">Z-A</option>
                    <option value="color">Color</option>
                 </select>

                 <select value={platformFilter} onChange={(e) => setPlatformFilter(e.target.value as Platform | 'all')} className="bg-gray-50 dark:bg-slate-700 sm:bg-transparent border-none rounded-lg text-sm px-3 py-2 flex-1 sm:flex-none">
                   <option value="all">Platforms</option>
                   <option value="instagram">Instagram</option>
                   <option value="facebook">Facebook</option>
                   <option value="x">X</option>
                   <option value="tiktok">TikTok</option>
                   <option value="website">Web</option>
                 </select>
              </div>
           </div>
        </header>

