              {/* Unfiled Categories Section (If Any - Logic handles legacy data or data imported before constraint) */}
              {displayTree.unfiled.length > 0 && (
                <div className="space-y-3 opacity-75">
                    <div className="flex items-center justify-between">
                        <h3 className="font-bold text-gray-900 dark:text-white">Unfiled (Legacy)</h3>
                        <span className="text-[10px] text-red-500 font-medium">Please move to folder</span>
                    </div>
                    <div className="space-y-2">
                       {displayTree.unfiled.map(c => (
                          <div key={c.id}>
                              <div className="flex items-center justify-between p-3 rounded-xl bg-gray-50 dark:bg-slate-800 border border-gray-100 dark:border-slate-700">
