      {/* Profile Details Modal (Existing) */}
      {selectedProfile && (
        <Modal isOpen={isPreviewOpen} onClose={() => setIsPreviewOpen(false)} title="Details">
           <div className="flex flex-col items-center mb-6">
              <h2 className="text-2xl font-bold mt-2 text-center">{selectedProfile.displayName || selectedProfile.username}</h2>
              <div className="flex gap-2 mt-2">
                <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-gray-100">{selectedProfile.platform}</span>
                <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-gray-100">{getCategoryName(selectedProfile.categoryId)}</span>
