                 <select value={profileSort} onChange={(e) => setProfileSort(e.target.value as SortOption)} className="bg-gray-50 dark:bg-slate-700 sm:bg-transparent border-none rounded-lg text-sm px-3 py-2 flex-1 sm:flex-none">
