import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Category, Profile, SortOption, PASTEL_COLORS, Platform, Folder } from './types';
import { Icons } from './components/Icon';
import { Modal } from './components/Modal';
import { ProfileCard } from './components/ProfileCard';

// --- CONFIGURATION ---
const APP_VERSION = '1.10'; // Custom Dropdowns

// Paste your logo URLs or Base64 strings inside the quotes below.
const BRANDING = {
  // The small icon/symbol (used if full logos aren't provided, or for favicon style usage)
  icon: "https://i.ibb.co/ccYGcz7f/logo-icon.png", 

  // Full logo for Light Mode (e.g., Dark text)
  logoLight: "https://i.ibb.co/5X7BwQkn/logo-full-darktext.png", 

  // Full logo for Dark Mode (e.g., White text)
  logoDark: "https://i.ibb.co/v4TcLNbr/logo-full-lighttext.png", 
};

// Initial Mock Data - Cleared as requested
const INITIAL_CATEGORIES: Category[] = [];
const INITIAL_PROFILES: Profile[] = [];
const INITIAL_FOLDERS: Folder[] = [];

// --- HELPER COMPONENT: Filter Pill (Custom Dropdown) ---
const FilterPill = ({ 
  icon: Icon, 
  label, 
  value, 
  onChange, 
  options, 
  isActive = false,
  variant = 'default' 
}: {
  icon: any,
  label: string,
  value: string,
  onChange: (val: string) => void,
  options: { value: string, label: string }[],
  isActive?: boolean,
  variant?: 'default' | 'highlight'
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const pillRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (pillRef.current && !pillRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    if (isOpen) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  return (
    <div className="relative" ref={pillRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center gap-2 px-4 py-2.5 rounded-full border shadow-sm transition-all cursor-pointer flex-shrink-0 group whitespace-nowrap ${
          variant === 'highlight' 
            ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-100 dark:border-indigo-800 text-indigo-700 dark:text-indigo-300'
            : isActive 
              ? 'bg-pink-50 dark:bg-pink-900/20 border-pink-200 dark:border-pink-800 text-pink-700 dark:text-pink-300'
              : 'bg-white dark:bg-slate-800 border-gray-200 dark:border-slate-700 text-gray-700 dark:text-gray-300 hover:border-pink-300 dark:hover:border-slate-500'
        }`}
      >
        <Icon className={`w-4 h-4 ${isActive || variant === 'highlight' ? 'opacity-100' : 'opacity-50 group-hover:opacity-100'}`} />

        <span className="text-xs font-semibold pr-1">
          {options.find(o => o.value === value)?.label || label}
        </span>

        <Icons.ChevronDown className={`w-3 h-3 opacity-40 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {/* Custom Dropdown Menu: Baby Blue Box with Black Text */}
      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-48 z-50 animate-in fade-in zoom-in-95 duration-200 origin-top-left">
           <div className="bg-blue-100 text-black rounded-xl shadow-xl border border-blue-200 overflow-hidden py-1 max-h-60 overflow-y-auto ring-1 ring-black/5">
              {options.map((opt) => (
                <div 
                  key={opt.value} 
                  onClick={() => {
                    onChange(opt.value);
                    setIsOpen(false);
                  }}
                  className={`px-4 py-2.5 text-sm font-medium cursor-pointer transition-colors flex items-center justify-between ${
                    value === opt.value 
                      ? 'bg-blue-200 text-blue-900' // Selected state within baby blue theme
                      : 'hover:bg-blue-50/50 hover:text-blue-800' // Hover state
                  }`}
                >
                  <span className="truncate">{opt.label}</span>
                  {value === opt.value && <Icons.Check className="w-3.5 h-3.5 text-blue-600 flex-shrink-0 ml-2" />}
                </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

export default function App() {
  // --- Auth State ---
  const [isAuthenticated, setIsAuthenticated] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('keepy_auth') === 'true';
    }
    return false;
  });
  const [loginCode, setLoginCode] = useState('');
  const [loginError, setLoginError] = useState('');

  // --- App State ---
  const [folders, setFolders] = useState<Folder[]>(() => {
    const saved = localStorage.getItem('keepy_folders');
    return saved ? JSON.parse(saved) : INITIAL_FOLDERS;
  });

