             className={`w-full flex items-center rounded-xl cursor-pointer transition-colors ${selectedCategoryId === null && selectedFolderId === null ? 'bg-gray-100 dark:bg-slate-800' : 'hover:bg-gray-50 dark:hover:bg-slate-800/50'}`}
