                             <div className="w-3 h-3 rounded-full" style={{backgroundColor: c.color}}></div>
                             <span className="text-sm font-medium">{c.name}</span>
                        </div>
                        {c.children.map(sub => (
                             <div key={sub.id} onClick={() => setNewProfileCategory(sub.id)} className={`ml-6 mt-1 flex items-center gap-2 p-2 rounded-lg border cursor-pointer ${newProfileCategory === sub.id ? 'border-pink-500 bg-pink-50' : 'border-gray-200'}`}>
                                 <div className="w-2 h-2 rounded-full" style={{backgroundColor: sub.color}}></div>
                                 <span className="text-xs">{sub.name}</span>
                             </div>
                        ))}
                     </div>
                ))}

             </div>
           </div>
           <div>
             <label className="block text-sm font-medium mb-1">Notes</label>
             <textarea className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 outline-none h-20" value={newProfileNotes} onChange={(e) => setNewProfileNotes(e.target.value)} />
           </div>
           <button onClick={handleSaveProfile} disabled={!newProfileUsername || !newProfileCategory} className="w-full py-3 bg-gradient-to-r from-pink-500 to-rose-500 text-white rounded-xl font-bold shadow-lg">Save Profile</button>
         </div>
      </Modal>

      {/* Folder Manager Modal */}
      <Modal isOpen={isManageFoldersOpen} onClose={() => setIsManageFoldersOpen(false)} title={editingFolderId ? "Edit Folder" : "New Folder"}>
          <div className="space-y-4">
              <div>
                  <label className="block text-sm font-medium mb-1">Folder Name</label>
                  <input type="text" className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 outline-none" placeholder="e.g. Work, Personal" value={newFolderName} onChange={(e) => setNewFolderName(e.target.value)} />
              </div>
              <button onClick={handleSaveFolder} disabled={!newFolderName} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700">{editingFolderId ? "Update Folder" : "Create Folder"}</button>
          </div>
      </Modal>

      {/* Category Modal */}
      <Modal isOpen={isAddCategoryOpen} onClose={() => { setIsAddCategoryOpen(false); setEditingCategoryId(null); }} title={editingCategoryId ? "Edit Category" : "New Category"}>
          <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium mb-1">Category Name</label>
               <input type="text" className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 outline-none" value={newCategoryName} onChange={(e) => setNewCategoryName(e.target.value)} />
             </div>
             {!newCategoryParent && (
                 <div>
                   <label className="block text-sm font-medium mb-1">Color</label>
                   <div className="flex flex-wrap gap-2">
                     {PASTEL_COLORS.map(color => (
                       <button key={color} onClick={() => setNewCategoryColor(color)} className={`w-8 h-8 rounded-full border-2 ${newCategoryColor === color ? 'border-gray-900 scale-110' : 'border-transparent'}`} style={{ backgroundColor: color }} />
                     ))}
                   </div>
                 </div>
             )}

             {/* Parent Selection */}
             <div>
               <label className="block text-sm font-medium mb-1">Parent Category (Optional)</label>
               <select className="w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 outline-none" value={newCategoryParent} onChange={(e) => setNewCategoryParent(e.target.value)} disabled={!!editingCategoryId && categories.some(c => c.parentId === editingCategoryId)}>
                 <option value="">None (Top Level)</option>
                 {categories.filter(c => !c.parentId && c.id !== editingCategoryId).map(c => (
                   <option key={c.id} value={c.id}>{c.name}</option>
                 ))}
               </select>
             </div>

             {/* Folder Selection (Required if Top Level) */}
             {!newCategoryParent && (
                 <div>
                    <label className="block text-sm font-medium mb-1">Folder <span className="text-red-500">*</span></label>
                    <select 
                        className={`w-full p-3 rounded-xl bg-gray-50 dark:bg-slate-900 border dark:border-slate-700 outline-none ${!newCategoryFolder ? 'border-red-300' : 'border-gray-200'}`} 
                        value={newCategoryFolder} 
                        onChange={(e) => setNewCategoryFolder(e.target.value)}
                        required
                    >
                        <option value="">-- Select Folder (Required) --</option>
                        {folders.map(f => (
                            <option key={f.id} value={f.id}>{f.name}</option>
                        ))}
                    </select>
