                                    <span className="font-semibold">{f.name}</span>
                                </div>
                                <div className="flex gap-1">
                                    <button onClick={() => handleOpenFolderModal(f)} className="p-2 text-gray-400 hover:text-blue-500"><Icons.Edit2 className="w-4 h-4"/></button>
