             {loginError && <p className="text-red-500 text-xs">{loginError}</p>}
             <button type="submit" className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-xl font-bold">Unlock App</button>
           </form>
        </div>
      </div>
    );
  }

  // --- Main App ---
  return (
