                                                        <button onClick={() => toggleCategoryExpand(c.id)} className="text-gray-400">
                                                            {expandedCategoryIds.includes(c.id) ? <Icons.ChevronDown className="w-4 h-4"/> : <Icons.ChevronRight className="w-4 h-4"/>}
