                                    <button onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat.id); }} className="p-1.5 text-gray-400 hover:text-red-500"><Icons.Trash2 className="w-3.5 h-3.5" /></button>
                                </div>
                          </div>
