                    <option value="">-- Choose Category --</option>
                    {categories
                        .filter(c => {
                             if (!newProfileFolderId) return false;
                             if (newProfileFolderId === 'unfiled') return !c.parentId && !c.folderId;
                             return !c.parentId && c.folderId === newProfileFolderId;
