      return parsed.map((p: any) => ({
        ...p,
        // Migration: Ensure platform exists and migrate twitter -> x
        platform: (p.platform === 'twitter' ? 'x' : p.platform) || 'instagram'
      }));
    }
    return INITIAL_PROFILES;
  });

  const [darkMode, setDarkMode] = useState(() => {
