  }, [profiles]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('keepy_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('keepy_theme', 'light');
