                    if (cat) {
                        let folderId = cat.folderId;
                        let parentCat = null;

                        if (cat.parentId) {
                            parentCat = categories.find(c => c.id === cat.parentId);
                            if (parentCat && parentCat.folderId) folderId = parentCat.folderId;
                        } else {
                            parentCat = cat; // It is the parent
